ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS ai_clinical_summary text;

UPDATE public.patients SET ai_clinical_summary = 'Patient is a 68-year-old male admitted via ED with fever (38.9°C), tachycardia, and hypotension. Urinalysis positive for nitrites and leukocyte esterase; blood cultures pending. Initiated on broad-spectrum IV antibiotics (piperacillin-tazobactam) and 30 mL/kg crystalloid bolus per Surviving Sepsis bundle. Lactate trending down from 3.8 to 2.1. Hemodynamically improving; remains on telemetry. Plan: continue antibiotics, monitor I/Os, repeat lactate in 6h, urology consult if no improvement in 24h.' WHERE mrn = 'MRN-771902';

UPDATE public.patients SET ai_clinical_summary = 'Patient is 42-year-old female, POD#1 following uncomplicated laparoscopic cholecystectomy for symptomatic cholelithiasis. Tolerating clear liquids, ambulating with assistance, pain controlled on PO regimen (5/10 to 2/10 with oxycodone 5mg). No fever, vitals stable. Incisions clean/dry/intact. Plan: advance diet as tolerated, transition to PO pain meds only, anticipate discharge home today pending bowel function and PO tolerance. Follow-up with surgery in 2 weeks.' WHERE mrn = 'MRN-902551';

UPDATE public.patients SET ai_clinical_summary = 'Patient is an 81-year-old female with HFrEF (EF 30%) presenting with progressive dyspnea, 4kg weight gain over 5 days, and bilateral lower extremity edema. CXR: pulmonary vascular congestion. BNP 1,840. Started on IV furosemide 40mg BID with net negative 1.8L since admission. SpO2 improved from 89% RA to 94% on 2L NC. Continuing home metoprolol and lisinopril. Plan: aggressive diuresis, daily weights, strict I/Os, cardiology following, consider discharge once euvolemic.' WHERE mrn = 'MRN-884213';

UPDATE public.patients SET ai_clinical_summary = 'Patient is a 74-year-old male with severe COPD (GOLD stage III, 40 pack-year history) admitted with acute exacerbation triggered by viral URI. Presenting with increased dyspnea, productive cough with purulent sputum, and wheezing. Started on systemic corticosteroids (methylprednisolone 40mg IV q8h), nebulized albuterol/ipratropium q4h, and azithromycin. SpO2 maintained 90-92% on 2L NC. Plan: continue bronchodilators, taper steroids over 5 days, pulmonary rehab referral, smoking cessation counseling already provided.' WHERE mrn = 'MRN-650118';